<?php $logoToken=!empty($workspace['logo_path'])?hash_hmac('sha256',(string)App\Core\Auth::workspaceId(),(string)App\Core\Env::get('APP_KEY','')):''; $logoUrl=$logoToken?'/mail/logo/'.(int)App\Core\Auth::workspaceId().'?token='.$logoToken:''; ?><div class="page-head"><div><h1>Nastavení firmy</h1><div class="sub">Údaje firmy, které se používají v dokladech, PDF a automatických e-mailech.</div></div></div><form class="form" method="post" enctype="multipart/form-data"><div class="card"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><h3>Logo firmy</h3><p>PNG, JPG nebo SVG, maximálně 2 MB. Logo se použije v aplikaci, PDF dokladech a HTML e-mailech.</p><?php if(!empty($workspace['logo_path'])): ?><div style="display:flex;align-items:center;gap:14px;margin:12px 0"><img src="<?=\App\Core\View::e($logoUrl)?>" alt="Logo firmy" style="max-width:180px;max-height:70px;object-fit:contain;border:1px solid #e5eaf2;border-radius:12px;padding:8px;background:#fff"><span class="badge ok">Logo nahráno</span></div><?php endif; ?><div class="field"><label for="logo">Nové logo</label><input id="logo" type="file" name="logo" accept="image/png,image/jpeg,image/svg+xml"></div></div><div class="card business-type-card"><h3>Typ podnikání</h3><p>Byznio podle něj přizpůsobí přehledy a doporučené moduly. Typ můžete kdykoli změnit.</p><div class="business-type-grid"><?php foreach(\App\Config\BusinessTypes::all() as $key=>$bt): ?><label class="business-type-option"><input type="radio" name="business_type" value="<?=\App\Core\View::e($key)?>" <?=((string)($workspace['business_type']??'services')===$key)?'checked':''?>><span class="business-type-image"><img src="/assets/business/<?=\App\Core\View::e($bt['image'])?>" alt=""></span><span class="business-type-copy"><b><?=\App\Core\View::e($bt['name'])?></b><small><?=\App\Core\View::e($bt['intro'])?></small></span></label><?php endforeach; ?></div></div><div class="card module-settings-card"><div class="section-head"><div><h3>Funkce a moduly</h3><p>Typ podnikání určuje doporučené nastavení. Jednotlivé funkce si ale můžete kdykoli zapnout nebo vypnout podle toho, co vaše firma skutečně používá.</p></div><span class="badge ok" id="moduleCount"></span></div><div class="module-settings-grid"><?php foreach(($module_catalog??[]) as $mk=>$mod): $checked=in_array($mk,($enabled_modules??[]),true); $core=$mk==='invoicing'; ?><label class="module-setting-option <?= $checked?'is-on':'' ?> <?= $core?'is-core':'' ?>"><input type="checkbox" name="modules[]" value="<?=\App\Core\View::e($mk)?>" <?= $checked?'checked':'' ?> <?= $core?'disabled':'' ?>><span class="module-setting-check"></span><span class="module-setting-copy"><b><?=\App\Core\View::e($mod['name'])?></b><small><?=\App\Core\View::e($mod['description'])?></small><?php if($core): ?><em>Základ Byznia</em><?php endif; ?></span></label><?php endforeach; ?></div><input type="hidden" name="modules[]" value="invoicing"><div class="module-settings-actions"><button type="button" class="btn" id="applyRecommendedModules">Použít doporučené podle typu podnikání</button><span class="sub">Nic se nezmění bez uložení nastavení.</span></div></div><div class="card"><div class="field"><label>Název firmy</label><input name="name" value="<?=\App\Core\View::e($workspace['name'])?>" required></div><div class="row"><div class="field"><label>IČO</label><input name="ico" value="<?=\App\Core\View::e($workspace['ico'])?>"></div><div class="field"><label>DIČ</label><input name="dic" value="<?=\App\Core\View::e($workspace['dic'])?>"></div></div><div class="row"><div class="field"><label>Ulice</label><input name="street" value="<?=\App\Core\View::e($workspace['street'])?>"></div><div class="field"><label>Město</label><input name="city" value="<?=\App\Core\View::e($workspace['city'])?>"></div></div><div class="row"><div class="field"><label>PSČ</label><input name="zip" value="<?=\App\Core\View::e($workspace['zip'])?>"></div><div class="field"><label>IBAN / bankovní účet</label><input name="bank_account" value="<?=\App\Core\View::e($workspace['bank_account'])?>" placeholder="CZ6508000000192000145399 nebo 123456789/0800" pattern="(?:CZ[0-9]{22}|[0-9]{1,10}/[0-9]{4}|[0-9]{1,10}-[0-9]{1,10}/[0-9]{4})"></div></div><div class="row"><div class="field"><label>E-mail</label><input name="email" value="<?=\App\Core\View::e($workspace['email'])?>"></div><div class="field"><label>Telefon</label><input name="phone" value="<?=\App\Core\View::e($workspace['phone'])?>"></div></div></div><div class="card"><h3>Automatické e-maily</h3><p>Odesílatel: <b><?=\App\Core\View::e($workspace['email_localpart']??'firma')?>@<?=\App\Core\View::e($mail_domain)?></b></p><div class="row"><div class="field"><label>Adresa před @</label><input name="email_localpart" value="<?=\App\Core\View::e($workspace['email_localpart']??'')?>" pattern="[A-Za-z0-9._-]+"></div><div class="field"><label>Jméno odesílatele</label><input name="mail_display_name" value="<?=\App\Core\View::e($workspace['mail_display_name']??$workspace['name']??'')?>" placeholder="Např. Jan Novák"></div></div><p>Vyhrazené názvy jako info, help, support, admin, billing nebo sales jsou určeny pouze pro Byznio.</p><p><label class="switch"><input type="checkbox" name="mail_enabled" <?=!empty($workspace['mail_enabled'])?'checked':''?>><span class="track"></span><span>Posílat e-maily za mě</span></label></p><div class="row"><label class="switch"><input type="checkbox" name="mail_invoices" <?=!empty($workspace['mail_invoices'])?'checked':''?>><span class="track"></span><span>Faktury</span></label><label class="switch"><input type="checkbox" name="mail_reminders" <?=!empty($workspace['mail_reminders'])?'checked':''?>><span class="track"></span><span>Upomínky</span></label><label class="switch"><input type="checkbox" name="mail_receipts" <?=!empty($workspace['mail_receipts'])?'checked':''?>><span class="track"></span><span>Potvrzení plateb</span></label><label class="switch"><input type="checkbox" name="mail_offers" <?=!empty($workspace['mail_offers'])?'checked':''?>><span class="track"></span><span>Nabídky</span></label><label class="switch"><input type="checkbox" name="mail_orders" <?=!empty($workspace['mail_orders'])?'checked':''?>><span class="track"></span><span>Objednávky</span></label><label class="switch"><input type="checkbox" name="mail_proformas" <?=!empty($workspace['mail_proformas'])?'checked':''?>><span class="track"></span><span>Zálohové faktury</span></label><label class="switch"><input type="checkbox" name="mail_credits" <?=!empty($workspace['mail_credits'])?'checked':''?>><span class="track"></span><span>Dobropisy</span></label></div><div class="row"><label class="switch"><input type="checkbox" name="weekly_report_enabled" <?=!empty($workspace['weekly_report_enabled'])?'checked':''?>><span class="track"></span><span>Týdenní report</span></label><label class="switch"><input type="checkbox" name="monthly_report_enabled" <?=!empty($workspace['monthly_report_enabled'])?'checked':''?>><span class="track"></span><span>Měsíční report</span></label></div></div><div class="card"><h3>Číselné řady dokladů</h3><p class="sub">Nastavte vlastní prefix a číslo, od kterého bude každá řada pokračovat.</p><div class="row"><?php $seriesMap=[];foreach(($series??[]) as $sr)$seriesMap[$sr['doc_type']]=$sr;foreach(['invoice'=>'Faktury','offer'=>'Nabídky','order'=>'Objednávky','proforma'=>'Zálohové faktury','credit'=>'Dobropisy'] as $stype=>$slabel):$sr=$seriesMap[$stype]??['prefix'=>['invoice'=>'FV','offer'=>'CN','order'=>'OBJ','proforma'=>'ZAL','credit'=>'DOB'][$stype],'next_number'=>1];?><div class="card" style="box-shadow:none"><b><?=\App\Core\View::e($slabel)?></b><div class="row" style="margin-top:10px"><div class="field"><label>Prefix</label><input name="series_prefix_<?=\App\Core\View::e($stype)?>" value="<?=\App\Core\View::e($sr['prefix'])?>"></div><div class="field"><label>Další číslo</label><input type="number" min="1" name="series_next_<?=\App\Core\View::e($stype)?>" value="<?=\App\Core\View::e($sr['next_number'])?>"></div></div></div><?php endforeach;?></div></div><div class="card"><h3>GoPay pro tuto firmu</h3><p>Každá firma používá vlastní GoPay účet. Přihlašovací údaje se ukládají šifrovaně na serveru a nezobrazují se zpět.</p><?php if(!empty($gopay_connected)): ?><p><span class="badge ok">GoPay připojeno</span></p><label class="switch"><input type="checkbox" name="gopay_disconnect" value="1"><span class="track"></span><span>Odpojit GoPay účet</span></label><?php else: ?><div class="row"><div class="field"><label>GOID</label><input name="gopay_goid" inputmode="numeric"></div><div class="field"><label>Client ID</label><input name="gopay_client_id" autocomplete="off"></div></div><div class="field"><label>Client Secret</label><input type="password" name="gopay_client_secret" autocomplete="new-password"></div><?php endif; ?></div><div class="card multi-firm-card"><h3>Další firmy</h3><p>Více firem můžete spravovat pod jedním přihlášením. Každá firma má vlastní doklady, banky, sklad, e-mail i nastavení.</p><a class="btn" href="/firms/new">Přidat další firmu · 300 Kč / měsíc</a></div><button class="btn primary">Uložit</button></form>
<script>
(function(){
const form=document.querySelector('form.form'); if(!form)return;
const catalog=<?php echo json_encode($module_catalog??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
const btModules=<?php echo json_encode(array_map(fn($bt)=>$bt['modules']??[],($business_types??[])),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
const moduleMap={'Zakázky':'jobs','Fakturace':'invoicing','Kalendář':'calendar','Banka':'bank','CRM':'crm','Sklad':'inventory','Dodavatelé':'received_invoices'};
const common=['reports','mail','tasks','documents'];

const count=document.getElementById('moduleCount'); const boxes=[...form.querySelectorAll('input[name="modules[]"]:not([disabled])')];
function update(){const n=boxes.filter(x=>x.checked).length+1;if(count)count.textContent=n+' aktivních';boxes.forEach(x=>x.closest('.module-setting-option')?.classList.toggle('is-on',x.checked));}
boxes.forEach(x=>x.addEventListener('change',update));
function recommended(){const key=form.querySelector('input[name=business_type]:checked')?.value||'services';const labels=btModules[key]||[];return [...new Set(common.concat(labels.map(x=>moduleMap[x]).filter(Boolean)))];}
document.getElementById('applyRecommendedModules')?.addEventListener('click',function(){boxes.forEach(x=>x.checked=recommended().includes(x.value));update();});
update();
})();
</script>
<style>
.module-settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:16px}.module-setting-option{position:relative;display:flex;gap:12px;align-items:flex-start;border:1px solid #e5eaf2;border-radius:14px;padding:13px;background:#fff;cursor:pointer;transition:.15s}.module-setting-option:hover{border-color:#bfd3ef;background:#fbfdff}.module-setting-option.is-on{border-color:#9fc4f4;background:#f7fbff}.module-setting-option input{position:absolute;opacity:0;pointer-events:none}.module-setting-check{width:21px;height:21px;flex:0 0 21px;border:1.5px solid #b9c6d8;border-radius:6px;background:#fff;margin-top:1px;position:relative}.module-setting-option.is-on .module-setting-check{background:#1677ee;border-color:#1677ee}.module-setting-option.is-on .module-setting-check:after{content:'✓';position:absolute;inset:0;color:#fff;font-size:14px;font-weight:900;display:grid;place-items:center}.module-setting-copy{display:grid;gap:4px}.module-setting-copy b{font-size:14px}.module-setting-copy small{color:#6c7890;line-height:1.4}.module-setting-copy em{font-style:normal;font-size:10px;color:#1677ee;font-weight:800;text-transform:uppercase;letter-spacing:.05em}.module-setting-option.is-core{cursor:default}.module-settings-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:16px}.module-settings-actions .sub{font-size:12px}.module-settings-card .section-head p{margin:4px 0 0;max-width:760px}@media(max-width:760px){.module-settings-grid{grid-template-columns:1fr}}
</style>
